def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string must consist only of digits.
    Raises ValueError for invalid inputs.
    """
    # Basic validation
    if not isinstance(num_str, str):
        raise TypeError("num_str must be a string")
    if not num_str.isdigit():
        raise ValueError("num_str must contain only digits")
    if N != len(num_str):
        raise ValueError("N does not match the length of num_str")
    if N <= 0:
        raise ValueError("N must be positive")
    if K < 0:
        raise ValueError("K must be non‑negative")
    if K > N - 1:
        raise ValueError("K cannot exceed N-1 (positions between digits)")
    if K + 1 > N:
        raise ValueError("Cannot split into more parts than digits")

    # Pre‑compute integer values of all substrings to avoid repeated conversions
    val = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        num = 0
        for j in range(i + 1, N + 1):
            num = num * 10 + (ord(num_str[j - 1]) - 48)
            val[i][j] = num

    # DP table: dp[i][k] = max product for first i digits with k multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplications
    for i in range(1, N + 1):
        dp[i][0] = val[0][i]

    # Fill DP table
    for k in range(1, K + 1):
        # At least k+1 digits are needed to place k cuts
        for i in range(k + 1, N + 1):
            max_prod = 0
            # Split point j: last part starts at j, ends at i
            for j in range(k, i):
                prod = dp[j][k - 1] * val[j][i]
                if prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    return dp[N][K]

def polynomial_to_string(n: int, coeffs: list) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        TypeError: If inputs are of incorrect type.
        ValueError: If inputs are logically inconsistent (e.g., wrong length of coeffs).
    """
    # Basic type checks
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if not isinstance(coeffs, list):
        raise TypeError("coeffs must be a list")
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1")
    for c in coeffs:
        if not isinstance(c, int):
            raise TypeError("All coefficients must be integers")

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation: lengths must match
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse_mapping = {}

    for e, o in zip(encoded, original):
        # Check for contradictions in forward mapping
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

        # Check for contradictions in reverse mapping
        if o in reverse_mapping:
            if reverse_mapping[o] != e:
                return "Failed"
        else:
            reverse_mapping[o] = e

    # Ensure the mapping covers all 26 uppercase letters
    # If the alphabet is not strictly uppercase letters, we still require 26 distinct mappings
    if len(mapping) != 26 or len(reverse_mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps or "NO ANSWER!" if impossible.
    """
    # Basic input validation
    try:
        if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
            return "NO ANSWER!"
        for rule in rules:
            if not isinstance(rule, tuple) or len(rule) != 2:
                return "NO ANSWER!"
            src, tgt = rule
            if not isinstance(src, str) or not isinstance(tgt, str):
                return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

    # If already equal
    if A == B:
        return 0

    from collections import deque

    max_steps = 10
    visited = set()
    queue = deque()
    queue.append((A, 0))
    visited.add(A)

    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue
        next_steps = steps + 1
        for src, tgt in rules:
            if src == "":
                continue  # skip empty source to avoid infinite loop
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_steps
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, next_steps))
                start = idx + 1  # allow overlapping replacements
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Basic type validation
    if not isinstance(scenario, str):
        raise TypeError("scenario must be a string")
    if not isinstance(liar_count, set):
        raise TypeError("liar_count must be a set")
    if not isinstance(statements, dict):
        raise TypeError("statements must be a dictionary")
    if not isinstance(days_of_week, set):
        raise TypeError("days_of_week must be a set")

    # Normalize days_of_week to lowercase for case-insensitive comparison
    days_lower = {day.lower() for day in days_of_week}

    # Helper to determine if a statement is about a day of the week
    def is_day_statement(stmt: str) -> bool:
        stmt_lower = stmt.lower()
        return any(day in stmt_lower for day in days_lower)

    # Iterate over each participant and their statements
    for participant, stmt_list in statements.items():
        # Validate that each statement list is indeed a list
        if not isinstance(stmt_list, list):
            raise TypeError(f"Statements for participant '{participant}' must be a list")
        is_liar = participant in liar_count
        for stmt in stmt_list:
            if not isinstance(stmt, str):
                # Skip non-string statements
                continue
            stmt = stmt.strip()
            if not stmt:
                continue
            # Skip statements about the day of the week
            if is_day_statement(stmt):
                continue

            # Determine truth value of the statement
            truth = None
            if stmt == "I am guilty.":
                truth = (scenario == participant)
            elif stmt == "I am not guilty.":
                truth = (scenario != participant)
            elif stmt.endswith(" is guilty."):
                name = stmt[:-len(" is guilty.")].strip()
                truth = (scenario == name)
            elif stmt.endswith(" is not guilty."):
                name = stmt[:-len(" is not guilty.")].strip()
                truth = (scenario != name)
            else:
                # Unknown statement format; ignore it
                continue

            # Check consistency based on liar status
            if is_liar:
                if truth:
                    return False  # Liars cannot make true statements
            else:
                if not truth:
                    return False  # Truth-tellers cannot make false statements

    # All statements are consistent with the scenario
    return True

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 1:
        return 0

    # Compute LIS ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute LDS starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_len = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_len:
            max_len = bitonic_len

    return n - max_len
